import torch
from torch import nn
class RedeXor(nn.Module):
    def __init__(self):
        super().__init__()
        self.oculta = nn.Linear(2, 4)
        self.saida = nn.Linear(4, 1)
    def forward(self, x):
        h = torch.tanh(self.oculta(x))
        return self.saida(h)
rede = RedeXor()
print(sum(p.numel() for p in rede.parameters()))
